import java.io.*;
import java.util.*;

public class Main {
    static class Animal {
        public void sound() {
            System.out.println("Generic sound Generic sound");
        }
    }

    static class Dog extends Animal {
        @Override
        public void sound() {
            System.out.println("Bark! Bark!");
        }
    }

    static class Cat extends Animal {
        @Override
        public void sound() {
            System.out.println("Meow! Meow!");
        }
    }

    static class Cow extends Animal {
        @Override
        public void sound() {
            System.out.println("Moo! Moo!");
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String input = sc.nextLine().trim();
        sc.close();

        Animal animal;

        switch (input) {
            case "Dog":
                animal = new Dog();
                break;
            case "Cat":
                animal = new Cat();
                break;
            case "Cow":
                animal = new Cow();
                break;
            default:
                animal = new Animal();
                break;
        }

        animal.sound();
    }
}
